    r"^そのクリーチャーは、?次の相手のターン開始時にアンタップしない$",
    # S級侵略: 侵略上位キーワード。engine未対応=under-model(安全)
    r"^S級侵略\s*\[.{1,30}\][：:].{1,120}$",
    r"^S級侵略ZERO\s*\[.{1,30}\][：:].{1,120}$",
    # 相手クリーチャーのタップ着地(全体): engine未対応=under-model(安全)
