    # タップスキル: タップで発動する起動能力。engine未対応=under-model(安全)
    r"^タップスキル[：:].{1,250}$",
    # 墓地置かれ時複雑条件: engine未対応=under-model(安全)
    r"^このカードが墓地に置かれた時[、,]それが.{1,200}$",
