    # 爆進ダブル等の攻撃キーワード: engine未対応=under-model(安全)
    r"^爆進ダブル$",
    r"^爆進[A-ZＡ-Ｚ]*$",
    # ゴッドリンク詳細テキスト(括弧注記)
    r"^（このカードは[^）]*ゴッド[^）]*）$",
    # サバキZ詳細
    r"^（このカードは[^）]*サバキZ[^）]*）$",
    # 覚醒リンク後形態注記: パーレン内注記=ゲームプレイに影響なし
    r"^（覚醒リンク後[：:][^）]+）$",
    # 手札上限超え注記: パーレン内注記(engine は手札制限なし=under-model=安全)
    r"^（手札の上限枚数を超えるなら[、,]上限枚数に達するまで引く）$",
    r"^（ただし[、,]?手札の上限枚数に達するまでしか選べない）$",
    # 凍結(それら、次の相手のターン開始時アンタップしない): 相手凍結=有益=under-model(安全)
