    # 出たターンに相手プレイヤー攻撃可: engine未対応=under-model(安全)
    r"^バトルゾーンに出たターン[、,]相手プレイヤーを攻撃できる$",
    # シールドN以下かわりに自己破壊: engine未対応=under-model(安全)
    r"^自分のシールドが\d+つ以下なら[、,]自分のシールドがブレイクされる時[、,]かわりにこのクリーチャーを破壊する$",
