    r"^ただし[、,]?(?:コストは)?\d+以下にならない$",
    # ただし、コストはN以下にならず/N以上の文明数より少なくならない: コスト軽減付帯条件
    r"^ただし[、,]?コストは\d+(?:より少なくならず|以下にならず)[^。]{0,100}$",
    # 枚数比例パワー修整の変種(名前に/他の/BZ依存): engine未対応=under-model(安全)
