    # メテオバーンX: X枚版。engine未対応=under-model(安全)
    r"^メテオバーンX[：:].{1,250}$",
    # クリーチャーを攻撃できない: cannot_attack_creature で模擬済み(安全)
    r"^クリーチャーを攻撃できない$",
