    r"^自分の.{1,30}が(?:あれば|\d+(?:体|枚)以上あれば)[、,]両方を選ぶ$",
    # スーパー龍解後注記: パーレン内形態注記=ゲームプレイに影響なし
    r"^（スーパー龍解後[：:][^）]+）$",
    # P'S覚醒リンク: 複数体結合キーワード。engine未対応=under-model(安全)
    r"^P'S覚醒リンク[：:].{1,250}$",
    # 超無限進化/超無限GV等の進化宣言: engine は is_evolution で簡略模擬済み
    r"^超無限進化[：:－\-].{1,80}$",
    r"^無限進化[：:－\-].{1,40}$",
