    r"^自分[のが][^。]{1,45}は[、,]?.{0,24}[「『][^」』]{1,45}[」』]を得る$",
    r"^(?:これ(?:を装備した|を?クロスした|でクロスした)?)?クロスした[^。]{1,30}は[「『][^」』]{1,70}[」』]を得る$",
