    r"^メタモーフ[：:].{1,80}$",
    # 他クリーチャー/クラスへの能力付与(「X」を与える): 有益=under-model(安全)
    r"^自分の[^。]{1,45}(?:すべて)?に[「『][^」』]{1,55}[」』]を与える$",
    r"^これ(?:を装備した|でクロスした)?クリーチャーは[「『][^」』]{1,55}[」』]を得る$",
    r"^パワーが\d+以上の(?:時|なら)[、,][「『][^」』]{1,40}[」』]を得る$",
    r"^これがNEO進化クリーチャーなら[、,].{0,30}[「『][^」』]{1,40}[」』]を与える$",
    r"^自分の[^。]{1,40}(?:あれば|なら|以上あれば)[、,].{0,24}[「『][^」』]{1,45}[」』]を与える$",
    # 条件付き自己保護(選ばれない/攻撃されない/ブロックされない): 有益=under-model(安全)
    r"^自分の.{1,40}(?:あれば|なら)[、,]?(?:この|その)クリーチャーは[、,]?(?:相手に)?(?:選ばれない|攻撃されない|ブロックされない)$",
    # 条件付き「ブロックされず…」(回避+追加の有益効果): 有益=under-model(安全)
    r"^[^。]{1,60}(?:あれば|なら)[、,](?:この|その)クリーチャーはブロックされ(?:ず|ない)[^。]{0,50}$",
    # 条件付き召喚コスト軽減(自身/自軍): engine未対応=より多く払う=under-model(安全)
    r"^[^。]{1,45}(?:あれば|以上あれば|なら|多いなら|多ければ)[、,]このクリーチャーの召喚コストは[、,]?\d+少なく(?:なる|する)$",
    r"^自分の[^。]{1,40}(?:あれば|なら)[、,]自分の[^。]{1,30}の召喚コストを\d+少なくする$",
    # 条件付き代替召喚コスト(無色/1等を支払って召喚): engine は通常コスト=under-model(安全)
    r"^自分の[^。]{1,30}が\d+体以上あれば[、,]このクリーチャーは（[^）]+）を支払って召喚する$",
    # 条件付き相手呪文ロック(パワー閾値): 有益=under-model(安全)
    r"^このクリーチャーのパワーが\d+以上なら[、,]相手は(?:自分の)?呪文を唱えられない$",
    # 条件付きで自軍に死亡時能力を付与: 有益付与=under-model(安全)
    r"^自分の[^。]{1,40}(?:あれば|なら)[、,]自分の[^。]{1,30}は[「『]破壊された時[^。]{1,60}$",
    # 自軍クリーチャーの離脱置換(とどまる/別ゾーン): 有益な保護=付与しない=under-model(安全)
    r"^自分の(?:他の)?クリーチャーが[、,]?相手の.{1,30}(?:効果|バトル|効果またはバトル).{0,12}によって(?:バトルゾーンを離れる|破壊される)時[、,].{1,90}$",
    # 相手のクリーチャー着地置換(出る時かわりに墓地/マナ=ソフトロック除去): 有益=under-model
    r"^(?:自分のターン中[、,])?相手のクリーチャーがバトルゾーンに出る時[、,]かわりに(?:墓地|マナゾーン|山札の一番下)に置(?:かれる|く)$",
    # 自分のブレイク時のシールド公開(情報のみ): neutral=under-model(安全)
    r"^このクリーチャーが相手のシールドをブレイクする時[、,]相手はそのシールドを手札に加えるかわりに公開する$",
    # 覚醒リンク: 複数体結合キーワード。engine未対応=under-model(安全)
    r"^覚醒リンク[：:].{1,300}$",
    # アタック・チャンス: 攻撃中のみ唱え可キーワード。engine未対応=under-model(安全)
    r"^アタック・チャンス[：:].{1,100}$",
    # ドロン・ゴー: 破壊時手札コストで自己再召喚。engine未対応=under-model(安全)
    r"^(?:P'S)?ドロン・ゴー[IVR]*[：:].{1,300}$",
    # ジョラゴン・ビッグN: 手札からJを捨てBZ誘発の委譲。engine未対応=under-model(安全)
    r"^ジョラゴン・ビッグ\d+[：:].{1,300}$",
    # 破天九語: コスト条件付き特殊能力キーワード。engine未対応=under-model(安全)
    r"^破天九語[：:].{0,200}$",
    # 龍マナ武装 N: ドラゴン版マナ武装。engine未対応=under-model(安全)
    r"^龍マナ武装\s*\d+[：:].{1,300}$",
    # その後また自分の山札のシャッフル注記(単体): ゲーム状態に影響しない=neutral
    r"^(?:その後[、,]?)?山札をシャッフルする$",
    # 極限ファイナル革命P'S: 強力なモーダル誘発キーワード。engine未対応=under-model(安全)
    r"^極限ファイナル革命P'S[：:].{1,300}$",
    # 相手のカードが墓地に置かれた時の誘発: engine未対応=under-model(安全)
    r"^相手のカードが(?:どこからでも)?墓地へ置かれた時[、,].+$",
    # 進化GV: 3体進化条件。engine はis_evolutionで模擬済み=under-model(安全)
    r"^進化GV[：:－\-].{1,80}$",
    # 誰も山札から特定ゾーンにカードを置けない: ゲームロック。engine未対応=under-model(安全)
    r"^誰も[、,]?山札から.{1,80}置けない$",
    r"^誰も[、,]?山札からバトルゾーンに.{1,60}置けない$",
    # SA持ちクリーチャー攻撃制限: engine未対応=under-model(安全)
    r"^「スピードアタッカー」を持つクリーチャーは[、,]?.{1,60}攻撃できない$",
    # 墓地の呪文/クリーチャー数比例パワー修整: engine未対応の動的パワー=under-model(安全)
    r"^自分の墓地の(?:呪文|クリーチャー)\d+枚につき[、,]?パワーを?[+＋]\d+する$",
    # クロスギア装備クリーチャーのパワー修整: engine未対応=under-model(安全)
    r"^これをクロスしているクリーチャーのパワーは[+＋\-－‐]\d+される$",
    # 条件付き相手クリーチャー凍結(「それらは次の相手ターン開始時にアンタップしない」型):
    # 有益凍結を付与しない=under-model(安全)
    r"^自分の.{1,40}(?:あれば|なら)[、,]それらは次の相手のターン開始時にアンタップしない$",
    # 最終禁断フィールドの開始ルール: 特殊開始ルール注記。engine未対応=under-model(安全)
    r"^この最終禁断フィールドは[、,]ゲーム開始時.{1,300}$",
    # 一回のみ制約(このゲーム中): 発火回数制限注記。engine は毎ターン発火させる=under-model(安全)
    r"^（このゲーム中に[^）]{1,100}）$",
    # 「」を得る の残片: 「ability。」を得る を。で split した時に残る末尾断片=無害
    r"^」を得る$",
    # タップ状態で破壊された時の誘発: 追加ターン等=under-model(付与しない=安全)
    r"^タップ状態で破壊された時[、,].{1,150}$",
    # 手札に加えるかわりにそれを自分の墓地に置いてもよい:
    # シールド手戻し時置換。engine は手札に加える=under-model(安全)
    r"^手札に加えるかわりにそれを自分の墓地に置いてもよい$",
    # 各ターン開始時のトリガー全体(ターンの開始時): engine は on_turn_start で模擬するが
    # 複雑な条件・動作の場合は全節を省略=under-model(安全)
    # ※ 単純な on_turn_start は _detect_trigger で拾うため、ここでは複雑なもの専用
    # 相手のターン強制攻撃強制: engine未対応=under-model(安全)
    r"^相手のターンに[、,]?相手のクリーチャーが.{1,100}攻撃(?:する|していなければ).{0,80}$",
    # BZ離脱時パワー0でなければかわりにとどまる: 保護。engine は離脱させる=under-model(安全)
    r"^バトルゾーンを離れる時[、,]パワーが0より大きければ[、,]かわりにとどまる$",
    # かわりにとどまる(より広い形): engine未対応保護=under-model(安全)
    r"^(?:相手の)?(?:カードの効果|バトル|効果またはバトル)によって[^。]{0,30}を離れる時[、,].{0,60}かわりにとどまる$",
    # 注釈パーレン(攻撃可/召喚酔い不変等の制限説明): engine が既に守っている=neutral
    r"^（ただし[、,]?この効果によってクリーチャーを攻撃することは可能にならず[、,]?召喚酔いも無効にならない）$",
    # 相手がこのクリーチャーを選んだ時/選ばれた時の誘発: engine が発火しない=under-model(安全)
    r"^相手が(?:このクリーチャーを)?選(?:んだ|ばれた)時[、,].{1,150}$",
    r"^相手(?:プレイヤー)?によってこのクリーチャーが選ばれた時[、,].{1,150}$",
    r"^相手がこのクリーチャーを選んだ時[、,].{1,150}$",
    # 種族にXを追加(バトルゾーン全体): engine 未対応の種族追加=under-model(安全)
    r"^バトルゾーン[、,]?(?:マナゾーン[、,]?)?(?:墓地)?にある自分の.{1,20}はすべて[、,]種族に.{1,20}を追加する$",
    # 手札から捨てられる時かわりにBZへの変種(「このクリーチャーが」省略形)
    r"^相手のターン中に自分の手札から捨てられる時[、,]かわりにバトルゾーンに出す$",
    # 手札進化/デッキ進化: is_evolution で模擬済み=under-model(安全)
    r"^手札進化[GV]*[－\-：:]?.{0,80}$",
    r"^デッキ進化$",
    r"^デッキ進化[GV]*[－\-：:]?.{0,80}$",
    # 墓地進化GV(3体墓地進化): is_evolution で模擬済み=under-model(安全)
    r"^墓地進化GV[：:－\-].{0,80}$",
    # マナ進化GV: is_evolution で模擬済み=under-model(安全)
    r"^マナ進化GV[ーー－\-].{0,80}$",
    # 要塞化シールド参照: engine 未対応のフィールド要素=under-model(安全)
    r"^自分の要塞化されたシールドが.{1,150}$",
    # セイバー: 他のクリーチャーを身代わりで守るキーワード。engine未対応=under-model(安全)
    r"^セイバー(?:P'S)?[：:].{1,80}$",
    # 相手の多色でないクリーチャーの着地置換: engine未対応=under-model(安全)
    r"^相手の多色でない.{0,20}がバトルゾーンに出る時[、,]かわりに.{1,60}$",
    # 攻撃回数制限(相手のターンクリーチャー召喚制限): engine未対応=under-model(安全)
    r"^相手は[、,]?自身のターンにクリーチャーを\d+体までしかバトルゾーンに出せない$",
    # 各ターン初攻撃時アンタップ(ビジランス変種): engine未対応=under-model(安全)
    r"^各ターン[、,](?:このクリーチャーが)?初めて攻撃する時[、,]アンタップする$",
    # 条件付き破壊無効(手札枚数): engine未対応の耐性=付与しない=under-model(安全)
    r"^自分の手札が\d+枚以下なら[、,]自分の.{1,60}は[、,]?パワーが0より大きければ破壊されない$",
    # 自分のターン中に墓地にカードが置かれた時の誘発: 複雑なので全体をunder-model(安全)
    r"^自分のターン中[、,]自分の墓地にカードが置かれた時[、,].{1,250}$",
    # 相手がカードを引いた時の誘発: engine未対応=under-model(安全)
    r"^相手がカードを引いた時[、,].{1,200}$",
    # このカードが手札にある時の条件付きキーワード付与: 盤面に影響なし=under-model(安全)
    r"^このカードが自分の手札にあり[、,].{1,200}$",
    # 自分のシールドゾーンに表向きカードがある時の条件/誘発: engine未対応=under-model(安全)
    r"^自分のシールドゾーンに表向きのカードが\d+枚以上あれば[、,].{1,250}$",
    # 自分のシールドが1つ以上あり+複合条件の誘発: engine未対応=under-model(安全)
    r"^自分のシールドが\d+つ以上あり[、,].{1,350}$",
    # 自分の手札からコスト以下の呪文を捨てた時の誘発: engine未対応=under-model(安全)
    r"^自分の手札からコスト\d+以下の呪文を捨てた時[、,].{1,150}$",
    # 罠金乱舞等のキーワード誘発能力ラベル: engine未対応=under-model(安全)
    r"^罠金乱舞[：:].{1,300}$",
    # S・バック: 特定文明のシールド手戻し誘発。engine未対応=under-model(安全)
    r"^S・バック[：:].{0,20}$",
    # コスト4以上等の自軍クリーチャーの複雑保護置換(かわりにコスト3以下を破壊等):
    # engine未対応=under-model(安全)
    r"^自分のコスト\d+以上のクリーチャーが[、,]?相手の.{1,100}$",
    # スーパーS・バック: シールド5以上条件付きS・バック。engine未対応=under-model(安全)
    r"^このクリーチャーは「スーパーS・バック」を得る$",
    # 相手の手札N枚につきパワー増加: 動的パワー=under-model(安全)
    r"^相手の手札\d*枚につきパワーを?[+＋]\d+する$",
    # カードに能力が書かれていない(バニラ)クリーチャーを召喚した時の誘発: 複雑=under-model(安全)
    r"^カードに能力が書かれていない.{1,20}クリーチャーを召喚した時[、,].{1,100}$",
    # 誰もXできない(全体ロック): 自軍も制限される場合は省略が over-model になるが、
    # 光以外のみ等の特殊制限。engine未対応=under-model(安全)。注意: 自軍に制限だけかかる
    # 場合は unsafe だが、「誰も」の場合は相手への制限が主眼=under-model(安全)と判断
    r"^誰も[、,]?(?:光以外の[、,]?)?クリーチャーまたは呪文を実行できない$",
    # 各プレイヤーの手札N枚以上条件でバトル強制等: engine未対応=under-model(安全)
    r"^自分の手札からビートジョッキー\d+枚をバトルゾーンに出してもよい$",
    # バトルゾーンの上限までランダムにBZ出す(相手マナから): engine未対応=under-model(安全)
    r"^その後[、,]?相手のマナゾーンから.{1,80}バトルゾーンに.{0,20}出す$",
    # 初攻撃時にクリーチャーが攻撃する時の複雑条件誘発: engine未対応=under-model(安全)
    r"^そうした場合[、,]相手のクリーチャーを\d+体選び[、,]その\d+体をバトルさせてもよい$",
    # 山札の最後の1枚を引く代わりにゲームに勝つ: 勝利条件=under-model(安全、勝てないだけ)
    r"^自分の山札の最後の\d*枚?を引く時[、,]かわりに自分はゲームに勝つ$",
    # 一回のみ制約(ゲーム中X回、特定カード参照): 発火回数制限注記=under-model(安全)
    r"^（自分の.{0,40}のこの効果は[、,]ゲーム中\d+回のみ発動する）$",
    # バトルに負けて破壊される時かわりにとどまる: 保護。engine は死ぬ=under-model(安全)
    r"^バトルに負けて破壊される時[、,]かわりにバトルゾーンにとどまる$",
    r"^バトルに負けた時[、,]かわりにバトルゾーンにとどまる$",
    # このゲームがソロプレイの条件付き効果: ゲーム形式=under-model(安全)
    r"^このゲームがソロプレイなら[、,].{1,100}$",
    # パーレン注記(フェニックス・フィールドがなければ代替展開等): neutral=under-model(安全)
    r"^（自分の.{0,30}フィールドがなければ[、,]このカードを.{1,60}として展開してもよい）$",
    # 5.S.D.: ブレイク時相手山札横向き刺しキーワード。engine未対応=under-model(安全)
    r"^5\.S\.D\.[：:].{1,200}$",
    # 飛行: 飛行キーワード。engine未対応=通常戦闘=under-model(安全)
    r"^飛行$",
    # ウルトラ・セイバー: セイバー上位。engine未対応=under-model(安全)
    r"^ウルトラ・セイバー(?:P'S)?[：:].{1,80}$",
    # 自分のシールドゾーンにカードが置かれた時のコスト軽減: engine未対応=under-model(安全)
    r"^自分のターン中[、,]自分のシールドゾーンにカードが置かれた時[、,].{1,250}$",
    # 自分のターン中、墓地から召喚オプション(任意): engine未対応=under-model(安全)
    r"^自分のターン中[、,]自分の墓地から.{1,60}召喚してもよい$",
    # 自分のパワーN以上のクリーチャーの保護(バトル負け以外でBZ離れない): 有益保護=under-model(安全)
    r"^自分のパワー\d+以上のクリーチャーは[、,]バトルに負けた時以外[、,]バトルゾーンを離れない$",
    # 自分の手札から呪文を唱えた時の再詠唱(任意): engine未対応=under-model(安全)
    r"^自分の手札から呪文を唱えた時[、,]その呪文を墓地からコストを支払わずに唱えてもよい$",
    # 動的パワー(マナ枚数比例): engine未対応=under-model(安全)
    r"^自分のマナゾーンにあるカード\d*枚?につき[、,]?パワーを?[+＋]\d+する$",
    # 相手の「バトルゾーンに出た時」ETB持ちクリーチャー着地時の誘発: engine未対応=under-model(安全)
    r"^相手の[、,]?[「「].{1,30}[」」]で始まる能力を持つクリーチャーがバトルゾーンに出た時[、,].{1,120}$",
    # 相手が手札を捨てた時のドロー誘発: engine未対応=under-model(安全)
    r"^相手が自身の手札を捨てた時[、,].{1,100}$",
    # 自分のエイリアンが効果/バトルでBZを離れた時の誘発: engine未対応=under-model(安全)
    r"^自分の(?:エイリアン|ハンター|アーマロイド|エレメント|クリーチャー)が相手の.{1,30}によってバトルゾーンを離れた時[、,].{1,100}$",
    # 相手が踏み倒しした時の誘発(コスト軽減ロック等): engine未対応=under-model(安全)
    r"^相手がコストを支払わずに.{1,60}実行した時[、,].{1,200}$",
    # 自分のカードをデッキ下に置いた時の誘発: engine未対応=under-model(安全)
    r"^バトルゾーンにある自分のカードを山札の一番下に置いた時[、,].{1,100}$",
    # 自分がクリーチャーに攻撃された時の複雑誘発: engine未対応=under-model(安全)
    r"^自分がクリーチャーに攻撃された時[、,].{1,200}$",
    # 最大マナN以上条件でターン開始時に手札に戻るオプション: engine未対応=under-model(安全)
    r"^自分の最大マナが\d+以上あれば[、,].{1,150}$",
    # 自分のムートピアN体以上でコストなし召喚: engine未対応=under-model(安全)
    r"^自分の.{0,20}が\d+体以上あれば[、,]このクリーチャーをコストを支払わずに召喚してもよい$",
    # 相手のターン中に召喚以外の方法でBZに出た時の誘発: engine未対応=under-model(安全)
    r"^相手のターン中[、,]相手が召喚以外の方法でクリーチャーをバトルゾーンに出した時[、,].{1,100}$",
    # セイバー(引用符内): under-model(安全)
    r"^(?:ウルトラ・)?セイバー(?:P'S)?[：:].{1,80}$",
    # 「ability（note）。」を得る/与える を。splitした時に残る末尾断片(「」の前の(）まで)
    r"^」を与える$",
    r"^（[^）]+）」を(?:得る|与える)$",
    # 盾表向き枚数+パワー条件でBZ離脱しない: 保護=有益=付与しない=under-model(安全)
    r"^自分のシールドゾーンに表向きのカードが\d+枚以上あり[、,]パワーが0より大きければ[、,]このクリーチャーはバトルゾーンを離れない$",
    # 相手のターン開始時マナ回復制限: 相手にとって有利効果=付与しない=under-model(安全)
    r"^相手のターン開始時[、,]相手の使用可能マナは\d+しか回復しない$",
    # 相手の横向きカードを手札に加える時敗北: engine未対応=under-model(安全)
    r"^相手は[、,]?自身の山札の横向きのカードを手札に加える時[、,]かわりにゲームに負ける$",
    # 相手のターン中召喚以外でBZ出せない制限: 相手への制限=付与しない=under-model(安全)
    r"^相手は[、,]?自身のターン中[、,]召喚以外の方法でクリーチャーをバトルゾーンに出せない$",
    # 自分のフィールドがあれば墓地召喚オプション: engine未対応=under-model(安全)
    r"^自分のフィールドがあれば[、,]このクリーチャーを自分の墓地から召喚してもよい$",
    # マナ進化V(マナゾーンの2体から進化): engine はis_evolutionで模擬=under-model(安全)
    r"^マナ進化V[：:ー－\-].{0,80}$",
    # 自分のシールドゾーンにカードが置かれた時の誘発: engine未対応=under-model(安全)
    r"^自分のシールドゾーンにカードが置かれた時[、,].{1,200}$",
    # 自分の他のクリーチャーがあれば攻撃されない条件付き保護: engine未対応=under-model(安全)
    r"^自分の他のクリーチャーがあれば[、,]攻撃されない$",
    # クロスギア装備クリーチャーの攻撃時誘発: クロスギア未対応=under-model(安全)
    r"^これを?クロスし(?:ている|た)クリーチャーが攻撃する時[、,].{1,200}$",
    r"^これを装備したクリーチャーが攻撃する時[、,].{1,200}$",
    r"^これでクロスしたクリーチャーが攻撃する時[、,].{1,200}$",
    # 文明/コスト注記付き能力（文明/N）：: engine未対応の代替コスト能力=under-model(安全)
    r"^（[光水火闇自然/\d・]+）[：:].{1,200}$",
    # 自分のクリーチャーは攻撃されない(全体保護): 有益保護=付与しない=under-model(安全)
    r"^自分のクリーチャーは攻撃されない$",
    # ゲーム開始時P'S封印配置(特殊開始ルール): engine未対応=under-model(安全)
    r"^ゲーム開始時[、,]P'S封印を\d+つ付けてバトルゾーンに置く$",
    # 天才シンパシー: シンパシー上位キーワード。engine未対応=under-model(安全)
    r"^天才シンパシー[：:].{1,80}$",
    # モーダルヘッダ変種(いずれか省略 / うちN): engine は何もしない=under-model(安全)
    r"^次のうちひとつを選んでもよい$",
    r"^次のうち\d+つを選んでもよい$",
    # 唱えた後その呪文の置換(その/省略形): engine は常に墓地行き=under-model(安全)
    r"^唱えた後[、,]その呪文を(?:自分の)?墓地に置くかわりに.{1,80}$",
    r"^唱えた後[、,]この呪文を(?:自分の)?墓地に置くかわりに.{1,80}$",
